export function script(input) {
  const rawIssuer = String(input.issuerUrl || '').trim();
  let issuer = '';
  try {
    const parsed = new URL(rawIssuer);
    if (parsed.protocol === 'https:' && !parsed.username && !parsed.password) {
      parsed.search = '';
      parsed.hash = '';
      parsed.pathname = parsed.pathname.replace(/\/+$/, '');
      issuer = parsed.toString().replace(/\/$/, '');
    }
  } catch (_) {}
  const validIssuer = Boolean(issuer);
  const discoveryUrl = `${issuer || 'https://invalid.invalid'}/.well-known/openid-configuration`;
  return { expectedIssuer: issuer, validIssuer, discoveryUrl };
}

export function script(input) {
  const warnings = [];
  const findings = [];
  const asArray = (value) => Array.isArray(value) ? value : [];
  let metadata = input.data && typeof input.data === 'object' ? input.data : {};
  if ((!metadata || Object.keys(metadata).length === 0) && typeof input.rawBody === 'string') {
    try { metadata = JSON.parse(input.rawBody); } catch (_) { warnings.push('Discovery response body was not valid JSON.'); }
  }
  const status = Number(input.status || 0);
  const ok = status >= 200 && status < 300;
  const hasMetadata = Boolean(metadata && typeof metadata === 'object' && !Array.isArray(metadata) && Object.keys(metadata).length > 0);
  const explicitError = typeof metadata.error === 'string' && metadata.error.trim().length > 0 ? metadata.error.trim() : null;
  const plausibleDiscovery = Boolean(
    typeof metadata.issuer === 'string' &&
    typeof metadata.authorization_endpoint === 'string' &&
    typeof metadata.jwks_uri === 'string' &&
    Array.isArray(metadata.response_types_supported) &&
    Array.isArray(metadata.subject_types_supported) &&
    Array.isArray(metadata.id_token_signing_alg_values_supported)
  );
  const sourceStatus = {
    status,
    statusText: input.statusText || null,
    ok,
    explicitError,
    plausibleDiscovery,
    usable: ok && hasMetadata && !explicitError && plausibleDiscovery
  };
  if (!input.validIssuer) warnings.push('The issuer URL must be an HTTPS URL; the request was routed to invalid.invalid.');
  if (!sourceStatus.usable) {
    const reason = explicitError
      ? `explicit error ${explicitError}; no plausible discovery metadata`
      : ok && !plausibleDiscovery
        ? 'missing required discovery fields'
        : input.statusText || status || 'empty or malformed response';
    warnings.push(`OIDC discovery response has no usable metadata or plausible discovery metadata: ${reason}`);
  }
  if (input.validIssuer && sourceStatus.usable) {
    if (metadata.issuer !== input.expectedIssuer) findings.push({ severity: 'high', title: 'Discovery issuer does not match the requested issuer', evidence: { expectedIssuer: input.expectedIssuer || null, advertisedIssuer: metadata.issuer || null } });
    const insecureEndpoints = ['authorization_endpoint', 'token_endpoint', 'jwks_uri', 'userinfo_endpoint'].filter((key) => metadata[key] && !String(metadata[key]).startsWith('https://'));
    if (insecureEndpoints.length > 0) findings.push({ severity: 'high', title: 'Discovery metadata advertises a non-HTTPS endpoint', evidence: { endpointKeys: insecureEndpoints } });
    if (!asArray(metadata.code_challenge_methods_supported).includes('S256')) findings.push({ severity: 'medium', title: 'PKCE S256 is not advertised', evidence: { codeChallengeMethodsSupported: asArray(metadata.code_challenge_methods_supported) } });
    if (asArray(metadata.id_token_signing_alg_values_supported).includes('none')) findings.push({ severity: 'high', title: 'Unsigned ID tokens are advertised', evidence: { idTokenSigningAlgorithms: asArray(metadata.id_token_signing_alg_values_supported) } });
    const riskyResponseTypes = asArray(metadata.response_types_supported).map(String).filter((value) => {
      const tokens = value.trim().split(/\s+/).filter(Boolean);
      return tokens.includes('token') || tokens.includes('id_token');
    });
    if (riskyResponseTypes.length > 0) findings.push({ severity: 'medium', title: 'Potentially higher-risk response type is advertised', evidence: { responseTypesSupported: riskyResponseTypes } });
  }
  return { report: { summary: { expectedIssuer: input.expectedIssuer || null, findings: findings.length, status }, findings, warnings, sourceStatus, metadata: { issuer: metadata.issuer || null, authorizationEndpoint: metadata.authorization_endpoint || null, tokenEndpoint: metadata.token_endpoint || null, jwksUri: metadata.jwks_uri || null, userinfoEndpoint: metadata.userinfo_endpoint || null, codeChallengeMethodsSupported: asArray(metadata.code_challenge_methods_supported), idTokenSigningAlgorithms: asArray(metadata.id_token_signing_alg_values_supported), responseTypesSupported: asArray(metadata.response_types_supported) }, authorizationNotes: input.authorizationNotes || null, note: 'Advertised capability does not prove enforcement; validate relevant behavior only within authorized scope.', nextSteps: ['Confirm issuer matching is enforced by every relying party', 'Require HTTPS for all discovery-advertised endpoints', 'Prefer authorization code flow with PKCE S256 and validate server-side enforcement', 'Reject unsigned ID tokens and restrict accepted signing algorithms', 'Review advertised response types against relying-party policy'] } };
}
